111	    @Test
112	    void 并发拉取_同设备同发布单最多一条任务() throws Exception {
113	        deviceService.register(new RegisterDeviceRequest("req-d", "d1", "m1", "1.0.0", 5));
114	        long releaseId = releaseService.create(new CreateReleaseRequest("req-r", "m1", "1.0.0", "2.0.0", 100))
115	                .releaseId();
116	
117	        int threads = 8;
118	        List<Callable<PullResponse>> tasks = new ArrayList<>();
119	        for (int i = 0; i < threads; i++) {
120	            int seq = i;
121	            tasks.add(() -> taskService.pull("d1", "req-pull-" + seq));
122	        }
123	        List<Object> results = runConcurrently(tasks);
124	
125	        List<Long> taskIds = new ArrayList<>();
126	        for (Object result : results) {
127	            assertThat(result).isInstanceOf(PullResponse.class);
128	            PullResponse response = (PullResponse) result;
129	            assertThat(response.task()).isNotNull();
130	            taskIds.add(response.task().taskId());
131	        }
132	        assertThat(taskIds).allMatch(id -> id.equals(taskIds.get(0)));
133	        assertThat(taskRepository.countByReleaseAndDevice(releaseId, "d1")).isEqualTo(1);
134	    }
135	
136	    @Test
137	    void 并发创建_同型号至多一张ACTIVE发布单() throws Exception {
138	        List<Callable<Object>> tasks = new ArrayList<>();
139	        for (int i = 0; i < 2; i++) {
140	            int seq = i;
141	            tasks.add(() -> releaseService.create(
142	                    new CreateReleaseRequest("req-c" + seq, "m1", "1.0.0", "2.0.0", 10)).releaseId());
143	        }
144	        List<Object> results = runConcurrently(tasks);
145	
146	        long successes = results.stream().filter(r -> !(r instanceof Exception)).count();
147	        long conflicts = results.stream()
148	                .filter(r -> r instanceof ApiException ae && ae.status() == HttpStatus.CONFLICT)
149	                .count();
150	        assertThat(successes).isEqualTo(1);
151	        assertThat(conflicts).isEqualTo(1);
152	        Long active = jdbc.queryForObject(
153	                "SELECT COUNT(*) FROM release_order WHERE status = 'ACTIVE'", Long.class);
154	        assertThat(active).isEqualTo(1);
155	    }
156	
157	    @Test
158	    void 并发拉取与取消_最终状态一致() throws Exception {
159	        for (int round = 0; round < 10; round++) {
160	            String deviceId = "d" + round;
161	            String model = "m" + round;
162	            deviceService.register(new RegisterDeviceRequest("req-d" + round, deviceId, model, "1.0.0", 5));
163	            long releaseId = releaseService.create(
164	                    new CreateReleaseRequest("req-r" + round, model, "1.0.0", "2.0.0", 100)).releaseId();
165	            final int seq = round;
166	
167	            List<Object> results = runConcurrently(List.of(
168	                    (Callable<Object>) () -> taskService.pull(deviceId, "req-p" + seq),
169	                    (Callable<Object>) () -> releaseService.cancel(releaseId, "req-x" + seq)));
170	            assertThat(results).noneMatch(r -> r instanceof Exception && !(r instanceof ApiException));
171	
172	            assertThat(releaseService.findOrder(releaseId).status()).isEqualTo(ReleaseStatus.CANCELLED);
173	            Long pending = jdbc.queryForObject(
174	                    "SELECT COUNT(*) FROM rollout_task WHERE release_id = ? AND status = 'PENDING'",
175	                    Long.class, releaseId);
176	            assertThat(pending).as("取消后不得残留 PENDING 任务（第%d轮）", round).isZero();
177	        }
178	    }
