180	    @Test
181	    void 并发成功回执与取消_一致提交顺序且已成功不回滚() throws Exception {
182	        int successWins = 0;
183	        int cancelWins = 0;
184	        for (int round = 0; round < 10; round++) {
185	            String deviceId = "d" + round;
186	            String model = "m" + round;
187	            deviceService.register(new RegisterDeviceRequest("req-d" + round, deviceId, model, "1.0.0", 5));
188	            long releaseId = releaseService.create(
189	                    new CreateReleaseRequest("req-r" + round, model, "1.0.0", "2.0.0", 100)).releaseId();
190	            long taskId = taskService.pull(deviceId, "req-p" + round).task().taskId();
191	            final int seq = round;
192	
193	            List<Object> results = runConcurrently(List.of(
194	                    (Callable<Object>) () -> taskService.receipt(taskId,
195	                            new ReceiptRequest("req-s" + seq, ReceiptResult.SUCCESS)),
196	                    (Callable<Object>) () -> releaseService.cancel(releaseId, "req-x" + seq)));
197	
198	            Object receiptResult = results.get(0);
199	            TaskStatus finalStatus = taskRepository.findById(taskId).orElseThrow().status();
200	            String deviceVersion = deviceService.get(deviceId).currentVersion();
201	            if (finalStatus == TaskStatus.SUCCESS) {
202	                successWins++;
203	                assertThat(receiptResult).isNotInstanceOf(Exception.class);
204	                assertThat(deviceVersion).isEqualTo("2.0.0");
205	            } else {
206	                cancelWins++;
207	                assertThat(finalStatus).isEqualTo(TaskStatus.CANCELLED);
208	                assertThat(receiptResult).isInstanceOfSatisfying(ApiException.class,
209	                        ae -> assertThat(ae.status()).isEqualTo(HttpStatus.CONFLICT));
210	                assertThat(deviceVersion).isEqualTo("1.0.0");
211	            }
212	            // 取消后任务不再处于 PENDING，且已成功设备不回滚
213	            assertThat(finalStatus).isNotEqualTo(TaskStatus.PENDING);
214	        }
215	        assertThat(successWins + cancelWins).isEqualTo(10);
216	    }
