270	    @Test
271	    void 并发恢复与取消_按提交顺序产生唯一合法状态() throws Exception {
272	        int cancelFirst = 0;
273	        int resumeFirst = 0;
274	        for (int round = 0; round < 10; round++) {
275	            String model = "m" + round;
276	            deviceService.register(new RegisterDeviceRequest("req-d" + round, "d" + round, model, "1.0.0", 1));
