2	
3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.stereotype.Repository;
5	
6	import java.util.Optional;
7	
8	/**
9	 * 幂等去重记录数据访问。request_id 全局唯一，业务变更与去重记录在同一事务提交。
10	 */
11	@Repository
12	public class IdempotencyRepository {
13	
14	    public record IdempotencyRecord(String requestId, String api, String fingerprint, String responseBody) {
15	    }
16	
17	    private final JdbcTemplate jdbc;
18	
19	    public IdempotencyRepository(JdbcTemplate jdbc) {
20	        this.jdbc = jdbc;
21	    }
22	
23	    public Optional<IdempotencyRecord> find(String requestId) {
24	        return jdbc.query("SELECT request_id, api, fingerprint, response_body FROM idempotency_record"
25	                        + " WHERE request_id = ?",
26	                (rs, rowNum) -> new IdempotencyRecord(rs.getString("request_id"), rs.getString("api"),
27	                        rs.getString("fingerprint"), rs.getString("response_body")),
28	                requestId).stream().findFirst();
29	    }
