    public List<String> findMemberDeviceIds(long waveId) {
        return jdbc.query("SELECT device_id FROM release_wave_member WHERE wave_id = ? ORDER BY device_id",
                (rs, rowNum) -> rs.getString("device_id"), waveId);
    }
